@Service
public class AccountTransferService {

    private final AccountRepository accountRepository;

    public AccountTransferService(AccountRepository accountRepository) {
        this.accountRepository = accountRepository;
    }

    @Transactional(isolation = Isolation.READ_COMMITTED, timeout = 5)
    public void transferFunds(Long senderId, Long receiverId, BigDecimal amount) {
        // Enforce consistent locking order by ID to prevent database deadlocks
        Long firstId = senderId < receiverId ? senderId : receiverId;
        Long secondId = senderId < receiverId ? receiverId : senderId;

        Account firstAccount = accountRepository.findByIdForUpdate(firstId)
            .orElseThrow(() -> new EntityNotFoundException("Account not found"));
        Account secondAccount = accountRepository.findByIdForUpdate(secondId)
            .orElseThrow(() -> new EntityNotFoundException("Account not found"));

        Account sender = (senderId.equals(firstId)) ? firstAccount : secondAccount;
        Account receiver = (senderId.equals(firstId)) ? secondAccount : firstAccount;

        sender.setBalance(sender.getBalance().subtract(amount));
        receiver.setBalance(receiver.getBalance().add(amount));

        accountRepository.save(sender);
        accountRepository.save(receiver);
    }
}
